import { FormEvent, useState } from 'react';
import { JxInputField, JxSelect, JxSwitch, JxButton, JxAlert } from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function InviteTeammateForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [submitted, setSubmitted] = useState(false);

  const touched = email.length > 0;
  const isValidEmail = EMAIL_PATTERN.test(email);
  const showError = touched && !isValidEmail;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isValidEmail) return;
    setSubmitted(true);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '16px', maxWidth: '420px' }}>
      {submitted && (
        <JxAlert
          intent="success"
          title="Приглашение отправлено"
          onClose={() => setSubmitted(false)}
        >
          {email} получит приглашение в команду{notify ? ' и уведомление на почту' : ''}.
        </JxAlert>
      )}

      <form
        onSubmit={handleSubmit}
        style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}
      >
        <JxInputField
          label="Электронная почта"
          type="email"
          required
          placeholder="name@company.com"
          helperText="Мы отправим приглашение на этот адрес"
          errorText={showError ? 'Похоже, это не email' : undefined}
          value={email}
          onChange={(event) => setEmail(event.target.value)}
        />

        <JxSelect
          label="Роль"
          value={role}
          onValueChange={setRole}
          options={[
            { value: 'member', label: 'Участник' },
            { value: 'admin', label: 'Администратор' },
            { value: 'viewer', label: 'Наблюдатель' },
          ]}
        />

        <JxSwitch
          label="Отправить уведомление на почту"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <JxButton type="submit" variant="primary" disabled={!isValidEmail}>
          Пригласить
        </JxButton>
      </form>
    </div>
  );
}

